A \textbf{graph} $G = (V, E)$ has two parts:
\begin{itemize}[leftmargin=1.5em]
    \item $V$ --- a non-empty set of \textbf{vertices} (points / nodes).
    \item $E$ --- a set of \textbf{edges} (lines / connections), where
          each edge joins two vertices.
\end{itemize}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Core vocabulary:}}
\begin{center}
\begin{tabular}{|l|p{8.5cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Term} & \textbf{Plain meaning} \\
\hline
\textbf{Vertex / Node} & A dot in the graph diagram \\
\hline
\textbf{Edge} & A line connecting two vertices \\
\hline
\textbf{Endpoints} & The two vertices an edge touches \\
\hline
\textbf{Adjacent vertices} & Two vertices connected by an edge \\
\hline
\textbf{Incident} & An edge is \textit{incident to} its endpoints \\
\hline
\textbf{Loop} & An edge that connects a vertex to itself \\
\hline
\textbf{Multiple edges} & Two or more edges connecting the same
                          pair of vertices \\
\hline
\textbf{Order of $G$} & $|V|$ --- total number of vertices \\
\hline
\textbf{Size of $G$} & $|E|$ --- total number of edges \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}}
2021 Q1(viii), 2022 Q1(ix), 2023 Q1(iv--vii),
2024 Q1(ii), 2024 Q1(vii)

\vspace{0.5cm}


\begin{center}
\begin{tikzpicture}[
    vtx/.style={circle, draw=primaryblue, fill=primaryblue!18,
                minimum size=0.7cm, font=\small\bfseries, inner sep=0pt},
    lbl/.style={font=\small, text=darkgray}
]
\node[vtx] (a) at (0,   2.5){$a$};
\node[vtx] (b) at (2.5, 2.5){$b$};
\node[vtx] (c) at (4.5, 1.2){$c$};
\node[vtx] (d) at (2.5, 0)  {$d$};
\node[vtx] (e) at (0,   0)  {$e$};


\draw[thick, primaryblue] (a)--(b) node[midway, above, lbl]{$e_1$};
\draw[thick, primaryblue] (b)--(c) node[midway, above right, lbl]{$e_2$};
\draw[thick, primaryblue] (b)--(d) node[midway, right, lbl]{$e_3$};
\draw[thick, primaryblue] (d)--(e) node[midway, below, lbl]{$e_4$};
\draw[thick, primaryblue] (e)--(a) node[midway, left, lbl]{$e_5$};
\draw[thick, primaryblue] (a)--(d) node[midway, below left, lbl]{$e_6$};


\draw[->, gray, thin] (5.5, 3.2) node[right, lbl, align=left]
    {Vertex $b$\\(node)} -- (b);
\draw[->, gray, thin] (5.5, 1.8) node[right, lbl, align=left]
    {Edge $e_2$\\(line)} -- (3.6, 1.9);
\draw[->, gray, thin] (-1.8, 1.2) node[left, lbl, align=right]
    {$a$ and $b$\\are \textbf{adjacent}} -- (1.2, 2.5);

\node[font=\small\bfseries, text=primaryblue] at (2.2, -1.0)
    {$V=\{a,b,c,d,e\},\quad E=\{e_1,e_2,e_3,e_4,e_5,e_6\}$};
\node[font=\small, text=darkgray] at (2.2, -1.6)
    {Order $= 5$ vertices \quad Size $= 6$ edges};
\end{tikzpicture}
\end{center}

\vspace{0.3cm}

The \textbf{degree} of vertex $v$, written $\deg(v)$, is the
\textbf{number of edges incident to $v$}.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Special notes:}}
\begin{itemize}[leftmargin=1.5em]
    \item A \textbf{loop} at $v$ counts as \textbf{2} towards
          $\deg(v)$ (both ends touch $v$).
    \item $\deg(v) = 0$: vertex is \textbf{isolated} (no edges).
    \item $\deg(v) = 1$: vertex is a \textbf{pendant} (leaf).
\end{itemize}

\vspace{0.4cm}
\begin{tcolorbox}[colback=accentorange!8, colframe=accentorange,
                  arc=3pt, boxrule=0.8pt,
                  left=8pt, right=8pt, top=6pt, bottom=6pt]
\textbf{Handshaking Lemma:}
\[
    \sum_{v \in V} \deg(v) = 2\,|E|
\]
\textit{The sum of all vertex degrees equals twice the number of edges,
because every edge contributes 1 to each of its two endpoints.}
\end{tcolorbox}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Important corollary:}}
In any graph, the number of vertices with \textbf{odd degree} is
always \textbf{even}. (Since the total sum must be even.)

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2021 Q1(vii) ---
\textit{``A graph has 10 vertices each of degree 6. How many edges?''}

\textbf{Handshaking Lemma:}
\[
    \sum_{v \in V} \deg(v) = 2\,|E|
\]
\textit{The sum of all vertex degrees equals twice the number of edges,
because every edge contributes 1 to each of its two endpoints.}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Important corollary:}}
In any graph, the number of vertices with \textbf{odd degree} is
always \textbf{even}. (Since the total sum must be even.)

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2021 Q1(vii) ---
\textit{``A graph has 10 vertices each of degree 6. How many edges?''}
\end{definitionbox}

\vspace{0.5cm}


\begin{center}
\begin{tikzpicture}[
    vtx/.style={circle, draw=primaryblue, fill=primaryblue!18,
                minimum size=0.72cm, font=\small\bfseries,
                inner sep=0pt},
    ivtx/.style={circle, draw=gray, fill=gray!10,
                 minimum size=0.72cm, font=\small\bfseries,
                 inner sep=0pt},
    lbl/.style={font=\small\bfseries}
]

\node[vtx] (a) at (0,2){$a$};
\node[vtx] (b) at (2,3){$b$};
\node[vtx] (c) at (4,2){$c$};
\node[vtx] (d) at (2,1){$d$};
\node[ivtx](e) at (6,2){$e$};   % isolated

\draw[thick,primaryblue] (a)--(b);
\draw[thick,primaryblue] (a)--(d);
\draw[thick,primaryblue] (b)--(c);
\draw[thick,primaryblue] (b)--(d);
\draw[thick,primaryblue] (c)--(d);


\draw[thick,primaryblue] (c) to[out=30,in=330,looseness=5] (c);


\node[font=\scriptsize, text=accentorange] at (0,   1.25){deg=2};
\node[font=\scriptsize, text=accentorange] at (2,   3.6) {deg=3};
\node[font=\scriptsize, text=accentorange] at (4.5, 1.25){deg=4};
\node[font=\scriptsize, text=accentorange] at (2,   0.3) {deg=3};
\node[font=\scriptsize, text=gray]         at (6,   1.25){deg=0};


\node[font=\small, text=darkgray, align=left] at (8.5, 2.8){
    $e$ is \textbf{isolated}\\$(\deg=0)$
};
\draw[->,gray,thin] (7.5,2.6) -- (e);

\node[font=\small, text=darkgray, align=left] at (8.5, 1.5){
    Loop at $c$\\counts as $+2$
};
\draw[->,gray,thin] (7.3,1.9) -- (4.8,2.3);


\node[font=\small, text=primaryblue] at (3, -0.3)
    {$\sum\deg = 2+3+4+3+0 = 12 = 2\times6 = 2|E|$
     \textcolor{darkgreen}{\checkmark}};
\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 5.2: Degrees of vertices.
Vertex $e$ is isolated ($\deg=0$). Vertex $c$ has a loop (adds 2 to
degree). Handshaking Lemma: $\sum\deg = 12 = 2\times6$.}}
\end{center}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Classified by edge rules:}}
\begin{center}
\begin{tabular}{|l|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Type} & \textbf{Direction?} & \textbf{Loops?} &
\textbf{Multiple edges?} \\
\hline
Simple graph     & No  & No  & No  \\
Multigraph       & No  & No  & Yes \\
Pseudograph      & No  & Yes & Yes \\
Directed graph   & Yes & No  & No  \\
Directed multigraph & Yes & Yes & Yes \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{Classified by special structure:}}
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Graph} & \textbf{Structure} & \textbf{Number of edges} \\
\hline
Complete $K_n$ & Every pair joined by one edge & $\binom{n}{2}=\frac{n(n-1)}{2}$ \\
\hline
Bipartite & Vertices split into sets $A$, $B$; & Only edges between \\
          & no edges within each set & $A$ and $B$ \\
\hline
Complete bipartite $K_{m,n}$ & Every vertex in $A$ joined to every in $B$ & $mn$ \\
\hline
Cycle $C_n$ & Single cycle visiting all $n$ vertices & $n$ \\
\hline
Path $P_n$ & Line of $n$ vertices & $n-1$ \\
\hline
Wheel $W_n$ & $C_n$ + one central hub vertex & $2n$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2020 Q1(i) (complete
graph), 2020 Q1(ii) (bipartite graph), 2021 Q1(iv) (undirected vs
directed), 2024 Q1(viii) (bipartite), 2024 Q1(ix) ($K_n$)

\vspace{0.5cm}


\begin{center}
\begin{tikzpicture}[
    v/.style={circle, draw=primaryblue, fill=primaryblue!18,
              minimum size=0.6cm, font=\scriptsize\bfseries,
              inner sep=0pt},
    va/.style={circle, draw=accentorange, fill=accentorange!18,
               minimum size=0.6cm, font=\scriptsize\bfseries,
               inner sep=0pt},
    lbl/.style={font=\small\bfseries, text=primaryblue, align=center}
]


\node[lbl] at (1.0, 4.0){$K_4$ (complete)};
\node[v](k1) at (0.2,3.1){1}; \node[v](k2) at (1.8,3.1){2};
\node[v](k3) at (0.2,1.8){3}; \node[v](k4) at (1.8,1.8){4};
\foreach \x/\y in {k1/k2,k1/k3,k1/k4,k2/k3,k2/k4,k3/k4}
    \draw[thick,primaryblue] (\x)--(\y);


\node[lbl] at (5.0, 4.0){$K_{2,3}$ (complete bipartite)};
\node[va](u1) at (4.2,3.1){$u_1$}; \node[va](u2) at (5.8,3.1){$u_2$};
\node[v] (v1) at (3.6,1.8){$v_1$}; \node[v](v2) at (5.0,1.8){$v_2$};
\node[v] (v3) at (6.4,1.8){$v_3$};
\foreach \u in {u1,u2}
    \foreach \v in {v1,v2,v3}
        \draw[thick,primaryblue] (\u)--(\v);
\node[font=\scriptsize,text=accentorange] at (5.0,3.55){Set $A$};
\node[font=\scriptsize,text=primaryblue]  at (5.0,1.3) {Set $B$};


\node[lbl] at (9.0, 4.0){$C_5$ (cycle)};
\foreach \i/\angle in {1/90,2/162,3/234,4/306,5/18}
    \node[v](c\i) at ({9.0+1.1*cos(\angle)},{2.45+1.1*sin(\angle)}){\i};
\foreach \i/\j in {c1/c2,c2/c3,c3/c4,c4/c5,c5/c1}
    \draw[thick,primaryblue] (\i)--(\j);


\node[lbl] at (12.6, 4.0){$W_4$ (wheel)};
\node[va](hub) at (12.6,2.45){$h$};
\foreach \i/\angle in {1/90,2/0,3/270,4/180}
    \node[v](w\i) at ({12.6+1.1*cos(\angle)},{2.45+1.1*sin(\angle)}){\i};
\foreach \i/\j in {w1/w2,w2/w3,w3/w4,w4/w1}
    \draw[thick,primaryblue] (\i)--(\j);
\foreach \i in {w1,w2,w3,w4}
    \draw[thick,accentorange] (hub)--(\i);

\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 5.3: Four standard graph
families. $K_4$: all 6 possible edges. $K_{2,3}$: orange set $A$
connects to every node of blue set $B$. $C_5$: one cycle of 5.
$W_4$: orange hub connected to outer 4-cycle.}}
\end{center}

\vspace{0.5cm}


\begin{center}
\begin{tikzpicture}[
    v/.style={circle, draw=primaryblue, fill=primaryblue!18,
              minimum size=0.6cm, font=\scriptsize\bfseries,
              inner sep=0pt},
    lbl/.style={font=\small\bfseries, text=primaryblue, align=center}
]


\node[lbl] at (1.2,3.6){Simple graph};
\node[v](s1) at (0.3,2.7){$a$}; \node[v](s2) at (2.1,2.7){$b$};
\node[v](s3) at (1.2,1.5){$c$};
\draw[thick,primaryblue] (s1)--(s2)--(s3)--(s1);
