    {Has loop\\at vertex $a$};


\node[lbl] at (13.2,3.6){Directed graph};
\node[v](d1) at (12.3,2.7){$a$}; \node[v](d2) at (14.1,2.7){$b$};
\node[v](d3) at (13.2,1.5){$c$};
\draw[->,thick,primaryblue] (d1)--(d2);
\draw[->,thick,primaryblue] (d2)--(d3);
\draw[->,thick,primaryblue] (d3)--(d1);
\draw[->,thick,primaryblue] (d1) to[bend right=25] (d3);
\node[font=\scriptsize,text=darkgray,align=center] at (13.2,0.9)
    {Arrows show\\direction};

\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 5.4: Four graph types.
Simple: no loops, no parallel edges. Multigraph: parallel edges allowed.
Pseudograph: loops allowed. Directed: edges have direction (arrows).}}
\end{center}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Sequences of vertices and edges:}}
\begin{center}
\begin{tabular}{|l|p{4.5cm}|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Name} & \textbf{Rule} & \textbf{Example} \\
\hline
\textbf{Walk} & No restriction; vertices and edges may repeat &
    $a$-$b$-$c$-$b$-$d$ \\
\hline
\textbf{Trail} & Edges not repeated (vertices may repeat) &
    $a$-$b$-$c$-$a$-$d$ \\
\hline
\textbf{Path} & Neither vertices nor edges repeated &
    $a$-$b$-$c$-$d$ \\
\hline
\textbf{Closed walk} & Starts and ends at same vertex &
    $a$-$b$-$c$-$a$ \\
\hline
\textbf{Circuit} & Closed trail (no repeated edge) &
    $a$-$b$-$c$-$d$-$a$ \\
\hline
\textbf{Cycle} & Closed path (no repeated vertex except start$=$end) &
    $a$-$b$-$c$-$a$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textbf{Length} of a walk/path/cycle = number of \textbf{edges} in it.

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{Connectivity terms:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Connected graph:} a path exists between every pair
          of vertices.
    \item \textbf{Disconnected graph:} at least one pair has no path.
    \item \textbf{Connected component:} a maximal connected subgraph.
    \item \textbf{Cut vertex} (articulation point): removing this
          vertex disconnects the graph.
    \item \textbf{Bridge} (cut edge): removing this edge disconnects
          the graph.
\end{itemize}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2023 Q1(vii) ---
\textit{``Define a cut vertex.''}

\vspace{0.5cm}


\begin{center}
\begin{tikzpicture}[
    v/.style={circle, draw=primaryblue, fill=primaryblue!18,
              minimum size=0.62cm, font=\small\bfseries, inner sep=0pt},
    cv/.style={circle, draw=accentorange, fill=accentorange!25,
               minimum size=0.62cm, font=\small\bfseries, inner sep=0pt},
    lbl/.style={font=\small\bfseries, text=primaryblue, align=center}
]


\node[lbl] at (1.8, 3.8){Path $a$-$b$-$c$-$d$};
\node[v](pa) at (0.3,3.0){$a$}; \node[v](pb) at (1.2,3.0){$b$};
\node[v](pc) at (2.1,3.0){$c$}; \node[v](pd) at (3.0,3.0){$d$};
\draw[thick,primaryblue] (pa)--(pb)--(pc)--(pd);
\draw[->,thick,accentorange,dashed] (0.3,2.5) -- (3.0,2.5)
    node[midway,below,font=\scriptsize,text=accentorange]
    {length = 3 edges};


\node[lbl] at (6.5, 3.8){Cycle $a$-$b$-$c$-$a$};
\node[v](ca) at (5.5,3.0){$a$}; \node[v](cb) at (6.5,1.8){$b$};
\node[v](cc) at (7.5,3.0){$c$};
\draw[thick,primaryblue] (ca)--(cb)--(cc)--(ca);
\node[font=\scriptsize,text=darkgray] at (6.5,1.3)
    {closed, no repeated vertex};


\node[lbl] at (11.2,3.8){Connected \quad vs \quad Disconnected};

\node[v](n1) at (9.8, 3.0){1}; \node[v](n2) at (10.8,3.0){2};
\node[v](n3) at (10.3,2.2){3};
