\end{center}

\vspace{0.3cm}


\begin{center}
\begin{tikzpicture}[
    v/.style={circle, draw=primaryblue, fill=primaryblue!18,
              minimum size=0.65cm, font=\small\bfseries, inner sep=0pt},
    cv/.style={circle, draw=accentorange, fill=accentorange!28,
               minimum size=0.65cm, font=\small\bfseries, inner sep=0pt},
    lbl/.style={font=\small\bfseries, text=primaryblue}
]
\node[lbl] at (4.5, 3.5){Cut Vertex Example};

\node[v] (a) at (0.5, 2.5){$a$};
\node[v] (b) at (1.8, 3.1){$b$};
\node[cv](c) at (3.2, 2.5){$c$};   % cut vertex
\node[v] (d) at (4.6, 3.1){$d$};
\node[v] (e) at (5.9, 2.5){$e$};
\node[v] (f) at (4.6, 1.9){$f$};

\draw[thick,primaryblue] (a)--(b)--(c)--(a);
\draw[thick,primaryblue] (c)--(d)--(e)--(f)--(c);


\node[font=\small\bfseries,text=accentorange] at (3.2,1.7)
    {cut vertex $c$};
\draw[->,accentorange,thick] (3.2,1.9) -- (c);


\node[font=\small,text=darkgray,align=center] at (9.5,2.5){
    Remove $c$: two\\components remain:\\
    $\{a,b\}$ and $\{d,e,f\}$
};
\draw[->,gray,thin] (7.2,2.5) -- (5.4,2.5);

\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 5.5: Left --- path of length
3, cycle of length 3, connected vs disconnected. Right --- cut vertex
$c$ (orange): removing it splits the graph into two components
$\{a,b\}$ and $\{d,e,f\}$.}}
\end{center}

\vspace{0.5cm}

Graph $G$: $V=\{a,b,c,d,e,f\}$,
$E=\{(a,b),(a,c),(b,c),(c,d),(d,e),(d,f)\}$

\textbf{(a)} Find all simple paths from $a$ to $e$.

\textbf{(b)} Find a cycle in $G$.

\textbf{(c) [2023 Q1(vii)]} Define cut vertex. Find all cut vertices
of $G$.

\textbf{(d)} Is $G$ connected?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}

\begin{center}
\begin{tikzpicture}[
    v/.style={circle, draw=primaryblue, fill=primaryblue!18,
              minimum size=0.65cm, font=\small\bfseries, inner sep=0pt},
    cv/.style={circle, draw=accentorange, fill=accentorange!28,
               minimum size=0.65cm, font=\small\bfseries, inner sep=0pt}
]
\node[v] (a) at (0,2){$a$};
\node[v] (b) at (1.4,3){$b$};
\node[cv](c) at (2.8,2){$c$};
\node[cv](d) at (4.2,2){$d$};
\node[v] (e) at (5.5,3){$e$};
\node[v] (f) at (5.5,1){$f$};
\draw[thick,primaryblue] (a)--(b)--(c)--(a);
\draw[thick,primaryblue] (c)--(d)--(e);
\draw[thick,primaryblue] (d)--(f);
\node[font=\scriptsize,text=accentorange] at (2.8,1.3){cut};
\node[font=\scriptsize,text=accentorange] at (4.2,1.3){cut};
\end{tikzpicture}
\end{center}

\vspace{0.2cm}
\textbf{(a)} Simple paths from $a$ to $e$ (no repeated vertex):

Path 1: $a \to b \to c \to d \to e$ \quad (length 4)

Path 2: $a \to c \to d \to e$ \quad (length 3)

These are the only two (going through $b$ first always forces
re-using $c$ otherwise).

\textbf{(b)} $a \to b \to c \to a$ is a cycle of length 3.

\textbf{(c)} A \textbf{cut vertex} is a vertex whose removal
\textbf{increases the number of connected components}.

Removing $c$: $\{a,b\}$ and $\{d,e,f\}$ separate $\to$
\textbf{$c$ is a cut vertex}.

Removing $d$: $\{a,b,c\}$ and $\{e\}$ and $\{f\}$ separate $\to$
\textbf{$d$ is a cut vertex}.

Removing any other vertex leaves $G$ connected.

Cut vertices: $c$ and $d$ (shown in orange above).

\textbf{(d)} \textbf{Yes, $G$ is connected.} A path exists between
every pair of vertices (all reach each other through $c$ and $d$).

\vspace{0.7cm}

An \textbf{Euler path} is a trail that uses every \textbf{edge}
exactly once.

An \textbf{Euler circuit} is an Euler path that starts and ends at
the \textbf{same vertex}.

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ The Königsberg Bridge
Problem} (origin of graph theory, Euler 1736):} Is it possible to
walk through Königsberg crossing each of its 7 bridges exactly once?
Euler proved it is \textbf{not} possible by showing 4 vertices have
odd degree.

\vspace{0.4cm}
\begin{tcolorbox}[colback=primaryblue!6, colframe=primaryblue,
                  arc=3pt, boxrule=0.8pt,
                  left=8pt, right=8pt, top=6pt, bottom=6pt]
\textbf{Euler's Theorems (existence conditions):}
\begin{center}
\begin{tabular}{|l|p{8.5cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Type} & \textbf{Condition (necessary and sufficient)} \\
\hline
\textbf{Euler circuit} & Graph is \textbf{connected} AND every vertex
                         has \textbf{even degree} \\
\hline
\textbf{Euler path} & Graph is \textbf{connected} AND \textbf{exactly
                      two} vertices have \textbf{odd degree}
                      (start at one, end at the other) \\
\hline
\textbf{Neither} & More than 2 vertices have odd degree \\
\hline
\end{tabular}
\end{center}
\end{tcolorbox}

