\vspace{0.6cm}

\textcolor{primaryblue}{\textbf{For directed graphs (digraphs):}}
\[
    A_{ij} =
    \begin{cases}
        1 & \text{if there is a directed edge from }
              v_i \to v_j \\
        0 & \text{otherwise}
    \end{cases}
\]
\begin{itemize}[leftmargin=1.5em]
    \item The matrix is \textbf{not} necessarily symmetric.
    \item \textbf{Row $i$ sum} $=$ out-degree of $v_i$
          (edges leaving).
    \item \textbf{Column $j$ sum} $=$ in-degree of $v_j$
          (edges entering).
    \item \textbf{Loop at $v_i$}: entry $A_{ii} = 1$.
\end{itemize}

\vspace{0.4cm}
