\node[v](ve) at (3.5, 3.2){$e$};

\draw[thick,primaryblue] (va)--(vb)
    node[midway,above left,font=\scriptsize\bfseries,
         text=accentorange]{$e_1$};
\draw[thick,primaryblue] (va)--(vd)
