         text=accentorange]{$e_2$};
\draw[thick,primaryblue] (vd)--(vb)
    node[midway,left,font=\scriptsize\bfseries,
         text=accentorange]{$e_3$};
\draw[thick,primaryblue] (vb)--(ve)
    node[midway,above,font=\scriptsize\bfseries,
         text=accentorange]{$e_4$};
\draw[thick,primaryblue] (vd)--(vc)
    node[midway,below,font=\scriptsize\bfseries,
         text=accentorange]{$e_5$};
