\begin{center}
\begin{tabular}{|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Graph type} & \textbf{Entry $A_{ij}$} \\
\hline
Simple undirected & 1 if edge exists; 0 otherwise \\
\hline
Directed & 1 if directed edge $v_i \to v_j$ \\
\hline
Multigraph & Number of edges between $v_i$ and $v_j$ \\
