\textcolor{primaryblue}{\textbf{\faCheckCircle\ Incidence Matrix --- $n\times m$:}}
\begin{center}
\begin{tabular}{|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Graph type} & \textbf{Entry $M_{ij}$} \\
\hline
Undirected & 1 if $v_i$ is endpoint of $e_j$; else 0 \\
\hline
Directed & $+1$ if $e_j$ leaves $v_i$; $-1$ if $e_j$ enters \\
\hline
