$(u_1, u_2)$ & $(v_1, v_4)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_2, u_3)$ & $(v_4, v_3)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_3, u_4)$ & $(v_3, v_5)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_4, u_1)$ & $(v_5, v_1)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_4, u_5)$ & $(v_5, v_6)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_5, u_6)$ & $(v_6, v_2)$ & \textcolor{darkgreen}{\checkmark} \\
$(u_6, u_2)$ & $(v_2, v_4)$ & \textcolor{darkgreen}{\checkmark} \\
\hline
\end{tabular}
\end{center}

All 7 edges verified. \textbf{Graph A $\cong$ Graph B.} \qed

