\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Definition:}}
$G_1 \cong G_2$ iff $\exists$ bijection $f:V_1\to V_2$ such that
$(u,v)\in E_1 \Leftrightarrow (f(u),f(v))\in E_2$.

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Invariant checklist
--- fail any $\Rightarrow$ NOT isomorphic:}}
\begin{center}
\begin{tabular}{|c|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Step} & \textbf{Check} \\
\hline
1 & $|V_1| = |V_2|$ (same vertex count) \\
2 & $|E_1| = |E_2|$ (same edge count) \\
3 & Degree sequences match (sort and compare) \\
4 & Same number of connected components \\
5 & Same number of triangles / cycle structure \\
6 & Find explicit bijection $f$; verify every edge \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Exam strategy:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{To prove isomorphic:} find $f$ and verify
          \textbf{every} edge --- no shortcuts.
    \item \textbf{To disprove:} find \textbf{one} differing
          invariant --- that is sufficient.
    \item \textbf{Always check degree sequence first} --- it
          eliminates most cases instantly.
    \item If one failed attempt at a bijection occurs, try
          permuting assignments for same-degree vertices.
\end{itemize}

