\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Hamiltonian ---
Sufficient Conditions:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Dirac (Thm 5.8):} $\deg(v)\geq n/2$ for all $v$
          $\Rightarrow$ Hamiltonian circuit.
    \item \textbf{Ore (Thm 5.9):} $\deg(u)+\deg(v)\geq n$ for every
          non-adjacent pair $\Rightarrow$ Hamiltonian circuit.
    \item Both are \textbf{sufficient only} --- failing them does not
          rule out a Hamiltonian circuit.
    \item If both fail: find a circuit by direct trial, or show
          impossibility (e.g.\ pendant vertex).
\end{itemize}

