\hline
$K_1, K_2, K_3, K_4$ & Yes \\
\hline
$K_5$ & No (violates $e \leq 3v-6$) \\
\hline
$K_{3,3}$ & No (violates $e \leq 2v-4$) \\
\hline
All trees & Yes ($f = 1$) \\
\hline
All cycles $C_n$ & Yes \\
\hline
\end{tabular}
\end{center}

