\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Planar Graphs ---
Core Formulas:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Euler's formula:} $v - e + f = 2$
          (connected planar, includes outer face)
    \item \textbf{Simple graph bound:} $e \leq 3v-6$
          (necessary for planarity, $v\geq3$)
    \item \textbf{Bipartite bound:} $e \leq 2v-4$
          (bipartite, $v\geq3$)
    \item \textbf{$K_5$:} $e=10 > 9=3(5)-6$ $\Rightarrow$ non-planar
    \item \textbf{$K_{3,3}$:} $e=9 > 8=2(6)-4$ $\Rightarrow$ non-planar
\end{itemize}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\
Planarity question strategy:}}
\begin{enumerate}[leftmargin=2em]
    \item Check $e \leq 3v-6$. If violated $\Rightarrow$ non-planar.
    \item If bipartite, use $e \leq 2v-4$ instead.
    \item If not violated, use Euler's formula $f = 2-v+e$
          to count faces, or try a planar drawing.
\end{enumerate}

\newpage

Grows one \textbf{connected piece} from a starting vertex.
At every step the \textbf{cheapest edge} from the current piece
to any new vertex is added.

\vspace{0.25cm}
\textcolor{primaryblue}{\textbf{Steps:}}
\begin{enumerate}[leftmargin=2em, topsep=2pt, itemsep=1pt]
  \item Pick any starting vertex $s$. Set $T=\{s\}$.
  \item Find the minimum-weight edge $\{u,v\}$ with
        $u\in T$, $v\notin T$.
  \item Add $\{u,v\}$ and $v$ to $T$.
  \item Repeat until $T$ has all $n$ vertices.
\end{enumerate}

\vspace{0.2cm}
$T$ stays connected at every step.
One new vertex is added per step.

